def evaluate(
    donor_reputation: float,
    recipient_reputation: float,
    donor_action: str,
    recipient_action: str,
    my_reputation: float
) -> float:
    # Stern Judging: judge based on recipient's reputation and donor's action
    # If donor cooperates with a good recipient, become good; if defects against bad, become good; else bad.
    # Good: >0, Bad: <=0
    recipient_good = recipient_reputation > 0.0
    if donor_action == 'cooperate':
        if recipient_good:
            return 1.0
        else:
            return -1.0
    else:  # defect
        if recipient_good:
            return -1.0
        else:
            return 1.0

