        if recipient_reputation >= 0.0:
            new_rep = 1.0
        else:
            new_rep = -1.0
    else:  # defect
        if recipient_reputation < 0.0:
            new_rep = 1.0
        else:
            new_rep = -1.0
    # Clamp to ensure within [-1, 1]
    return max(-1.0, min(1.0, new_rep))

