    donor_reputation: float,
    recipient_reputation: float,
    donor_action: str,
    recipient_action: str,
    my_reputation: float
) -> float:
    step_coop = 0.3
    step_defect = 0.5
    if donor_action == 'cooperate':
        if recipient_reputation >= 0.0:
            new_rep = donor_reputation + step_coop
        else:
            new_rep = donor_reputation - step_coop
    else:  # defect
        if recipient_reputation >= 0.0:
            new_rep = donor_reputation - step_defect
        else:
            new_rep = donor_reputation + step_defect
    new_rep += my_reputation * 0.1
